import { isClearRequest } from './isClearRequest.mjs';
import { requireParams } from '../../helpers/parameters/requireParams.mjs';
import { isString } from '../../tools/objects.mjs';
import { TOURNAMENT_RECORD, PARTICIPANT_ID } from '../../constants/attributeConstants.mjs';
import { PARTICIPANT_NOT_FOUND } from '../../constants/errorConditionConstants.mjs';
