import { matchUpsOf, positionAssignmentsOf } from '../../helpers/drawTopology/structureMembers.mjs';
import { getLadderPolicy, isChallengeInRange } from '../../query/ladder/getLadderPolicy.mjs';
import { addAdHocMatchUps } from '../structures/addAdHocMatchUps.mjs';
import { addTimeItem } from '../timeItems/addTimeItem.mjs';
import { isLadder } from '../../query/drawDefinition/isLadder.mjs';
import { UUID } from '../../tools/UUID.mjs';
import { CHALLENGED } from '../../constants/matchUpStatusValues.mjs';
import { CHALLENGE_ISSUED } from '../../constants/ladderConstants.mjs';
import { SUCCESS } from '../../constants/resultConstants.mjs';
import { MISSING_DRAW_DEFINITION, INVALID_VALUES, MISSING_STRUCTURE_ID, STRUCTURE_NOT_FOUND, PARTICIPANT_NOT_FOUND } from '../../constants/errorConditionConstants.mjs';

function issueChallenge(params) {
    const { defenderParticipantId, challengerParticipantId, issuedAt, drawDefinition } = params;
    if (typeof drawDefinition !== 'object')
        return { error: MISSING_DRAW_DEFINITION };
    if (!isLadder(drawDefinition.drawType)) {
        return { error: INVALID_VALUES, info: 'issueChallenge requires a LADDER drawType' };
    }
    if (!challengerParticipantId || !defenderParticipantId)
        return { error: INVALID_VALUES };
    if (challengerParticipantId === defenderParticipantId) {
        return { error: INVALID_VALUES, info: 'a participant cannot challenge themselves' };
    }
    if (!issuedAt)
        return { error: INVALID_VALUES, info: 'issuedAt is required' };
    const structureId = params.structureId ?? drawDefinition.structures?.[0]?.structureId;
    if (typeof structureId !== 'string')
        return { error: MISSING_STRUCTURE_ID };
    const structures = drawDefinition.structures;
    const structure = structures?.find((s) => s.structureId === structureId);
    if (!structure)
        return { error: STRUCTURE_NOT_FOUND };
    const positionOf = (participantId) => positionAssignmentsOf(structure)?.find((a) => a.participantId === participantId)?.drawPosition;
    const challengerPosition = positionOf(challengerParticipantId);
    const defenderPosition = positionOf(defenderParticipantId);
    if (challengerPosition === undefined || defenderPosition === undefined) {
        return { error: PARTICIPANT_NOT_FOUND, info: 'both participants must be seated on the ladder' };
    }
    const policy = getLadderPolicy({ ...params, structure });
    if (!isChallengeInRange({ challengerPosition, defenderPosition, policy })) {
        return {
            error: INVALID_VALUES,
            info: `position ${challengerPosition} may not challenge position ${defenderPosition} — range is ${policy.challengeRange}`,
        };
    }
    const matchUpId = UUID();
    const matchUp = {
        matchUpId,
        matchUpStatus: CHALLENGED,
        sides: [
            { sideNumber: 1, participantId: challengerParticipantId },
            { sideNumber: 2, participantId: defenderParticipantId },
        ],
    };
    const addResult = addAdHocMatchUps({ ...params, matchUps: [matchUp], structureId });
    if (addResult.error)
        return addResult;
    const added = matchUpsOf(structure)?.find((m) => m.matchUpId === matchUpId);
    addTimeItem({
        timeItem: { itemType: CHALLENGE_ISSUED, itemValue: challengerParticipantId, itemDate: issuedAt },
        element: added,
    });
    return { ...SUCCESS, matchUpId };
}

export { issueChallenge };
