import { modifyEventPublishStatus } from '../events/modifyEventPublishStatus.mjs';
import { getEventPublishStatus } from '../../query/event/getEventPublishStatus.mjs';
import { requireParams } from '../../helpers/parameters/requireParams.mjs';
import { definedAttributes } from '../../tools/definedAttributes.mjs';
import { addNotice } from '../../global/state/globalState.mjs';
import { PUBLISH_EVENT_SEEDING, UNPUBLISH_EVENT_SEEDING } from '../../constants/topicConstants.mjs';
import { TOURNAMENT_RECORD, EVENT } from '../../constants/attributeConstants.mjs';
import { PUBLIC } from '../../constants/timeItemConstants.mjs';
import { SUCCESS } from '../../constants/resultConstants.mjs';

function publishEventSeeding({ removePriorValues = true, stageSeedingScaleNames, seedingScaleNames, tournamentRecord, status = PUBLIC, drawIds = [], event, }) {
    const paramsCheck = requireParams({ tournamentRecord, event }, [TOURNAMENT_RECORD, EVENT]);
    if (paramsCheck.error)
        return paramsCheck;
    const eventPubStatus = getEventPublishStatus({ event, status });
    const updatedSeedingScaleNames = (eventPubStatus?.seeding?.seedingScaleNames || seedingScaleNames) && {
        ...eventPubStatus?.seeding?.seedingScaleNames,
        ...seedingScaleNames,
    };
    const updatedStageSeedingScaleNames = (eventPubStatus?.seeding?.stageSeedingScaleNames || stageSeedingScaleNames) && {
        ...eventPubStatus?.seeding?.stageSeedingScaleNames,
        ...stageSeedingScaleNames,
    };
    const seeding = definedAttributes({
        stageSeedingScaleNames: updatedStageSeedingScaleNames,
        seedingScaleNames: updatedSeedingScaleNames,
        published: true,
        drawIds,
    });
    modifyEventPublishStatus({
        statusObject: { seeding },
        removePriorValues,
        status,
        event,
    });
    addNotice({
        topic: PUBLISH_EVENT_SEEDING,
        payload: {
            tournamentId: tournamentRecord.tournamentId,
            eventId: event.eventId,
            drawIds,
        },
    });
    return { ...SUCCESS };
}
function unPublishEventSeeding({ removePriorValues = true, seedingScaleNames, tournamentRecord, status = PUBLIC, drawIds, stages, event, }) {
    const paramsCheck = requireParams({ tournamentRecord, event }, [TOURNAMENT_RECORD, EVENT]);
    if (paramsCheck.error)
        return paramsCheck;
    const eventPubStatus = getEventPublishStatus({ event, status });
    if (eventPubStatus) {
        const seeding = eventPubStatus.seeding;
        if (Array.isArray(stages) && seeding.stageSeedingScaleNames) {
            for (const stage of stages) {
                if (seeding.stageSeedingScaleNames[stage]) {
                    delete seeding.stageSeedingScaleNames[stage];
                }
            }
        }
        if (Array.isArray(seedingScaleNames) && seeding?.seedingScaleNames) {
            seeding.seedingScaleNames = seeding.seedingScaleNames.filter((scaleName) => !seedingScaleNames.includes(scaleName));
        }
        if (Array.isArray(drawIds) && seeding?.drawIds) {
            seeding.drawIds = seeding.drawIds.filter((drawId) => !drawIds.includes(drawId));
        }
        if ((!Object.values(seeding.stageSeedingScaleNames ?? {}).length &&
            !seeding.seedingScaleNames?.length &&
            !seeding.drawIds?.length) ||
            (!stages && !seedingScaleNames && !drawIds?.length)) {
            delete seeding.stageSeedingScaleNames;
            delete seeding.seedingScaleNames;
            delete seeding.drawIds;
            seeding.published = false;
        }
        modifyEventPublishStatus({
            statusObject: { seeding },
            removePriorValues,
            status,
            event,
        });
    }
    addNotice({
        topic: UNPUBLISH_EVENT_SEEDING,
        payload: {
            tournamentId: tournamentRecord.tournamentId,
            eventId: event.eventId,
        },
    });
    return { ...SUCCESS };
}

export { publishEventSeeding, unPublishEventSeeding };
