import { validDateAvailability } from '../../validators/validateDateAvailability.mjs';
import { addNotice } from '../../global/state/globalState.mjs';
import { VENUE_NOT_FOUND, MISSING_VENUE_ID, COURT_EXISTS, MISSING_COURTS_INFO, INVALID_VALUES } from '../../constants/errorConditionConstants.mjs';
import { SUCCESS } from '../../constants/resultConstants.mjs';
import { extractDate, formatDate } from '../../tools/plainDate.mjs';
