import { setFirstClassOrExtension } from '../extensions/setFirstClassOrExtension.mjs';
import { deleteDrawDefinitions } from './deleteDrawDefinitions.mjs';
import { requireParams } from '../../helpers/parameters/requireParams.mjs';
import { getFlightProfile } from '../../query/event/getFlightProfile.mjs';
import { refreshEventDrawOrder } from './refreshEventDrawOrder.mjs';
import { TOURNAMENT_RECORD, DRAW_ID, EVENT } from '../../constants/attributeConstants.mjs';
import { FLIGHT_PROFILE } from '../../constants/extensionConstants.mjs';

function deleteFlightAndFlightDraw({ autoPublish = true, tournamentRecord, auditData, drawId, event, force }) {
    const paramsCheck = requireParams({ tournamentRecord, drawId, event }, [TOURNAMENT_RECORD, DRAW_ID, EVENT]);
    if (paramsCheck.error)
        return paramsCheck;
    const drawWasGenerated = event.drawDefinitions?.find((drawDefinition) => drawDefinition.drawId === drawId);
    if (drawWasGenerated) {
        const result = deleteDrawDefinitions({
            drawIds: [drawId],
            eventId: event.eventId,
            tournamentRecord,
            autoPublish,
            auditData,
            event,
            force,
        });
        if (result.error)
            return result;
    }
    const { flightProfile } = getFlightProfile({ event });
    if (flightProfile) {
        const flight = flightProfile.flights?.find((flight) => flight.drawId === drawId);
        if (flight) {
            const flights = flightProfile.flights.filter((flight) => {
                return flight.drawId !== drawId;
            });
            setFirstClassOrExtension({
                element: event,
                attribute: 'flightProfile',
                name: FLIGHT_PROFILE,
                value: { ...flightProfile, flights },
            });
        }
    }
    return refreshEventDrawOrder({ tournamentRecord, event });
}

export { deleteFlightAndFlightDraw };
