import { MISSING_OFFICIAL_RECORD, ASSIGNMENT_NOT_FOUND } from '../../constants/officiatingConstants.mjs';
import { INVALID_VALUES } from '../../constants/errorConditionConstants.mjs';
import { SUCCESS } from '../../constants/resultConstants.mjs';
import { nowIso } from '../../tools/clock.mjs';

function removeOfficialAssignment({ officialRecord, assignmentId }) {
    if (!officialRecord)
        return { error: MISSING_OFFICIAL_RECORD };
    if (!assignmentId)
        return { error: INVALID_VALUES, context: { message: 'Missing assignmentId' } };
    const index = officialRecord.assignments.findIndex((a) => a.assignmentId === assignmentId);
    if (index === -1)
        return { error: ASSIGNMENT_NOT_FOUND, context: { assignmentId } };
    officialRecord.assignments.splice(index, 1);
    officialRecord.updatedAt = nowIso();
    return { ...SUCCESS };
}

export { removeOfficialAssignment };
